int total_energy(int cells[], int n) {
    int total = 0;
    for (int i = 0; i < n; i++) {
        total += cells[i];
    }
    return total;
}

int total_energy(int cells[], int n) {
    int total = 0;
    int i = 0;
    while (i < n) {
        total = total + cells[i];
        i++;
    }
    return total;
}

int total_energy(int cells[], int n) {
    int total = 0;
    int i;
    for (i = n - 1; i >= 0; i--) {
        total += cells[i];
    }
    return total;
}

